mapper.select:
SELECT t2.`name` AS product_name, t2.one_price AS product_price, t4.`name` AS version_name, t4.unit_value AS unit_value, t5.short_name AS supplier_name, t6.`name` AS warehouse_name, t1.id, t1.batch_no, t1.inbound_date, t1.product_id, t1.inbound_price, t1.inbound_quantity, t1.quantity, t1.warehouse_id, t1.supplier_id, t1.note, t1.create_time, t1.update_time, t1.creator, t1.updater FROM zc_product_batch t1 LEFT JOIN zc_product t2 ON t1.product_id = t2.id AND t2.deleted = 0 LEFT JOIN zc_product_version t4 ON t2.version_id = t4.id AND t4.deleted = 0 LEFT JOIN zc_supplier t5 ON t1.supplier_id = t5.id AND t5.deleted = 0 LEFT JOIN zc_warehouse t6 ON t1.warehouse_id = t6.id AND t6.deleted = 0 WHERE t1.deleted = 0
AND t1.batch_no LIKE CONCAT('%', #{reqVO.batchNo}, '%')
AND t1.inbound_date BETWEEN #{reqVO.inboundDate[0]} AND #{reqVO.inboundDate[1]}
AND t1.product_id = #{reqVO.productId}
AND t1.warehouse_id = #{reqVO.warehouseId}
AND t1.supplier_id = #{reqVO.supplierId}
AND t1.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
ORDER BY t1.id DESC
